<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/admin.php';send_cors_headers();$context=require_admin('customers.manage');$db=get_db();$method=$_SERVER['REQUEST_METHOD']??'GET';if($method==='GET'){$id=trim((string)($_GET['id']??''));if($id!==''){$purpose=trim((string)($_GET['purpose']??''));if(mb_strlen($purpose)<10)json_response(422,['success'=>false,'message'=>'A data-access purpose is required.']);$stmt=$db->prepare('SELECT id,first_name,last_name,email,mobile,email_verified,status,date_of_birth,gender,anniversary_date,created_at,last_login_at FROM users WHERE id=:id');$stmt->execute(['id'=>$id]);$customer=$stmt->fetch();if(!$customer)json_response(404,['success'=>false,'message'=>'Customer not found.']);$db->prepare('INSERT INTO data_access_logs (admin_id,subject_type,subject_id,purpose,fields_json,created_at) VALUES (:admin,"customer",:subject,:purpose,:fields,UTC_TIMESTAMP())')->execute(['admin'=>$context['admin']['id'],'subject'=>$id,'purpose'=>$purpose,'fields'=>json_encode(array_keys($customer))]);json_response(200,['success'=>true,'customer'=>$customer]);}$stmt=$db->query('SELECT u.id,u.first_name,u.last_name,u.email,u.mobile,u.status,u.email_verified,u.created_at,COUNT(o.id) order_count,COALESCE(SUM(o.total_amount),0) lifetime_value FROM users u LEFT JOIN orders o ON o.user_id=u.id GROUP BY u.id ORDER BY u.created_at DESC LIMIT 500');json_response(200,['success'=>true,'customers'=>$stmt->fetchAll()]);}if($method==='POST'){$body=get_json_body();$id=trim((string)($body['customer_id']??''));$status=trim((string)($body['status']??''));$reason=trim((string)($body['reason']??''));if(!in_array($status,['active','restricted','blocked'],true)||($status!=='active'&&mb_strlen($reason)<10))json_response(422,['success'=>false,'message'=>'Valid account status and reason are required.']);$stmt=$db->prepare('SELECT status FROM users WHERE id=:id');$stmt->execute(['id'=>$id]);$from=$stmt->fetchColumn();if($from===false)json_response(404,['success'=>false,'message'=>'Customer not found.']);$db->prepare('UPDATE users SET status=:status,updated_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['status'=>$status,'id'=>$id]);if($status!=='active')revoke_principal_sessions('customer',$id,'account_'.$status);record_status_change('customer',$id,(string)$from,$status,$reason?:null);audit_event('admin.customer_status_changed','customer',$id,['status'=>$status,'reason'=>$reason]);json_response(200,['success'=>true,'message'=>'Customer account updated.']);}json_response(405,['success'=>false,'message'=>'Method not allowed.']);
